pair_ts=collections.defaultdict(list)
for u,v,t in E: pair_ts[(min(u,v),max(u,v))].append(t)

def closures(g,delta=800):
    res=set()
    for i in range(len(g)):
        for j in range(i+1,len(g)):
            a,b=g[i],g[j]
            abts=pair_ts.get((min(a,b),max(a,b)),[])
            if not abts: continue
            ca=collections.defaultdict(list); cb=collections.defaultdict(list)
            for c,t in adj[a]: ca[c].append(t)
            for c,t in adj[b]: cb[c].append(t)
            for c in set(ca)&set(cb):
                if c in (a,b): continue
                for t1 in ca[c]:
                    for t2 in cb[c]:
                        wt=max(t1,t2)
                        for t in abts:
                            if wt<=t<=wt+delta: res.add((t,a,b)); break
    return res
